import * as T from 'three';
import {makeTrack,createWorld,createCar} from './world.js';
import {Race,drive,pilot,clamp,angle,wrap,formatTime} from './race.js';
const $=id=>document.getElementById(id),canvas=$('game'),track=makeTrack(),race=new Race(track.length);
let world;try{world=createWorld(canvas,track);}catch(error){$('load').textContent='WebGL could not start. Please enable hardware acceleration and reload.';throw error;}
const {renderer,scene,camera,sun,sky}=world;
const colors=['#e8b84d','#e4e7df','#d65c40','#256c75'];
const cars=colors.map((c,i)=>{let model=createCar(c,i===0);scene.add(model);return{model,x:0,z:0,heading:0,speed:0,vx:0,vz:0,steering:0,s:0,total:0,lane:(i%2===0?-1:1)*3,target:44-i*1.5,hit:0};});
const player=cars[0],keys={},touch={};let paused=false,demo=false,assisted=false,now=0,toastEnd=0,accumulator=0,last=performance.now(),bestLap=Infinity,bestRace=Infinity,camReady=false,lastCount='',collisionCount=0;
try{bestLap=Number(localStorage.getItem('aurel.bestLap.v1'))||Infinity;bestRace=Number(localStorage.getItem('aurel.bestRace.v1'))||Infinity;}catch{}
function storeBest(){try{localStorage.setItem('aurel.bestLap.v1',String(bestLap));localStorage.setItem('aurel.bestRace.v1',String(bestRace));}catch{}}
function grid(){cars.forEach((c,i)=>{const s=4+(3-i)*7,p=track.at(s);Object.assign(c,{x:p.x+p.nx*c.lane,z:p.z+p.nz*c.lane,heading:p.heading,speed:0,vx:0,vz:0,steering:0,s,total:s,hit:0});updateCar(c,0);});race.lastS=player.s;camReady=false;}
// The initial player starts behind the field. Lap progress begins at the start line.
function setupGrid(){cars.forEach((c,i)=>{const s=i===0?2:10+(i-1)*7,p=track.at(s);Object.assign(c,{x:p.x+p.nx*c.lane,z:p.z+p.nz*c.lane,heading:p.heading,speed:0,vx:0,vz:0,steering:0,s,total:s,hit:0});updateCar(c,0);});race.lastS=player.s;camReady=false;collisionCount=0;}
let audio=null,sound=false;
function initAudio(){if(audio)return;const ctx=new(window.AudioContext||window.webkitAudioContext)(),gain=ctx.createGain(),filter=ctx.createBiquadFilter();gain.gain.value=0;filter.type='lowpass';filter.frequency.value=500;filter.connect(gain);gain.connect(ctx.destination);const osc=ctx.createOscillator(),sub=ctx.createOscillator();osc.type='sawtooth';sub.type='triangle';osc.connect(filter);sub.connect(filter);osc.start();sub.start();audio={ctx,gain,filter,osc,sub};}
function toggleSound(){initAudio();sound=!sound;audio.ctx.resume();$('sound').textContent=sound?'SOUND ON':'SOUND OFF';}
function beep(freq=600,dur=.1){if(!sound||!audio)return;const o=audio.ctx.createOscillator(),g=audio.ctx.createGain();o.frequency.value=freq;o.connect(g);g.connect(audio.ctx.destination);g.gain.setValueAtTime(.08,audio.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.ctx.currentTime+dur);o.start();o.stop(audio.ctx.currentTime+dur);}
function notify(text){$('toast').textContent=text;toastEnd=now+2.3;}
function start(isDemo=false){demo=isDemo;assisted=isDemo;paused=false;race.start();setupGrid();document.body.classList.add('racing');for(const id of ['menu','carlabel','menufooter','overlay'])$(id).hidden=true;$('hud').hidden=false;$('demoBadge').hidden=!demo;$('count').textContent='3';$('resume').hidden=false;canvas.focus();if(sound)audio?.ctx.resume();}
function garage(){race.reset();paused=false;demo=false;document.body.classList.remove('racing');for(const id of ['menu','carlabel','menufooter'])$(id).hidden=false;for(const id of ['hud','overlay','demoBadge'])$(id).hidden=true;$('count').textContent='';$('toast').textContent='';setupGrid();}
function togglePause(){if(!['racing','countdown'].includes(race.state))return;paused=!paused;$('overlay').hidden=!paused;if(paused){$('overline').textContent='RACE PAUSED';$('resultTitle').textContent='Take a breath.';$('resultText').textContent='The coast can wait.';$('results').innerHTML='';$('resume').hidden=false;}else{last=performance.now();canvas.focus();}clearInput();}
function finish(){const valid=!assisted;if(valid){bestLap=Math.min(bestLap,...race.lapTimes);bestRace=Math.min(bestRace,race.elapsed);storeBest();}const position=getPosition();$('overline').textContent=demo?'EXHIBITION COMPLETE':'CROWN CIRCUIT / COMPLETE';$('resultTitle').textContent=position===1?'The crown is yours.':'A golden finish.';$('resultText').textContent=`P${position} of 4 · ${assisted?'Exhibition drive · personal records disabled':'Three laps. One unforgettable machine.'}`;$('results').innerHTML=race.lapTimes.map((t,i)=>`<div><span>LAP 0${i+1}</span><strong>${formatTime(t)}</strong></div>`).join('')+`<div><span>TOTAL TIME</span><strong>${formatTime(race.elapsed)}</strong></div><div><span>PERSONAL BEST</span><strong>${formatTime(bestRace)}</strong></div>`;$('resume').hidden=true;$('overlay').hidden=false;$('demoBadge').hidden=true;beep(1000,.4);}
function recover(){if(race.state!=='racing')return;const p=track.at(player.s);Object.assign(player,{x:p.x,z:p.z,heading:p.heading,speed:0,vx:0,vz:0,steering:0});race.elapsed+=3;camReady=false;notify('BACK ON TRACK / +3.00s');}
function clearInput(){for(const k in keys)keys[k]=false;for(const k in touch)touch[k]=false;}
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code==='Escape'||e.code==='KeyP')togglePause();if(e.code==='KeyR')recover();if(e.code==='KeyM')toggleSound();if(e.code==='Enter'&&race.state==='grid')start();});addEventListener('keyup',e=>keys[e.code]=false);addEventListener('blur',()=>{clearInput();if(!paused&&['racing','countdown'].includes(race.state))togglePause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&!paused&&['racing','countdown'].includes(race.state))togglePause();});
for(const b of document.querySelectorAll('[data-key]')){const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);touch[k]=true;});for(const e of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(e,()=>touch[k]=false);}
$('start').onclick=()=>start();$('tour').onclick=()=>start(true);$('takeover').onclick=()=>{demo=false;$('demoBadge').hidden=true;notify('YOUR TURN. TAKE THE WHEEL.');canvas.focus();};$('sound').onclick=toggleSound;$('pause').onclick=togglePause;$('resume').onclick=togglePause;$('restart').onclick=()=>start(demo);$('garage').onclick=garage;document.querySelector('.brand').onclick=e=>{e.preventDefault();if(race.state==='grid')return;if(!paused)togglePause();};
const skidGeometry=new T.PlaneGeometry(.24,.9),skidMat=new T.MeshBasicMaterial({color:'#111c20',transparent:true,opacity:.35,depthWrite:false}),skids=new T.InstancedMesh(skidGeometry,skidMat,500),dummy=new T.Object3D();skids.count=0;scene.add(skids);let skidIndex=0,skidClock=0;
function tireMarks(){for(const side of [-1,1]){dummy.position.set(player.x+Math.cos(player.heading)*side, .045,player.z-Math.sin(player.heading)*side);dummy.rotation.set(-Math.PI/2,0,-player.heading);dummy.updateMatrix();skids.setMatrixAt(skidIndex%500,dummy.matrix);skidIndex++;}skids.count=Math.min(skidIndex,500);skids.instanceMatrix.needsUpdate=true;}
function updateCar(c,dt){c.model.position.set(c.x,0,c.z);c.model.rotation.y=c.heading;c.model.userData.body.rotation.z=T.MathUtils.lerp(c.model.userData.body.rotation.z,-c.steering*c.speed*.003,Math.min(1,dt*8));for(const w of c.model.userData.wheels){w.wheel.rotation.x+=c.speed*dt/.53;w.pivot.rotation.y=w.front?c.steering:0;} }
function getPosition(){return 1+cars.slice(1).filter(c=>c.total>player.total).length;}
function physics(dt){if(paused)return;const before=race.state;race.tick(dt);if(race.state==='countdown'){const label=String(Math.max(1,Math.ceil(race.countdown)));if(label!==lastCount){lastCount=label;beep(450,.1);}return;}if(before==='countdown'&&race.state==='racing'){beep(900,.2);notify('GO / CLAIM THE COAST');}
 if(race.state!=='racing')return;
 for(let i=0;i<cars.length;i++){let c=cars[i],input=i===0&&!demo?{throttle:keys.KeyW||keys.ArrowUp||touch.throttle,brake:keys.KeyS||keys.ArrowDown||touch.brake,steer:(keys.KeyA||keys.ArrowLeft||touch.left?1:0)-(keys.KeyD||keys.ArrowRight||touch.right?1:0),drift:!!keys.Space}:pilot(c,track,c.lane,i===0?47:c.target);
 // Left turns increase heading when the camera follows positive Z.
 drive(c,input,dt);const near=track.nearest(c.x,c.z);if(Math.abs(near.offset)>8.7)c.speed*=Math.exp(-dt*.8);
 if(Math.abs(near.offset)>10.1){const side=Math.sign(near.offset);c.x=near.x+near.nx*side*10.1;c.z=near.z+near.nz*side*10.1;const outward=c.vx*near.nx*side+c.vz*near.nz*side;if(outward>0){c.vx-=near.nx*side*outward*1.25;c.vz-=near.nz*side*outward*1.25;c.speed*=.76;c.heading+=angle(near.heading-c.heading)*.18;if(i===0&&now-c.hit>.6){collisionCount++;notify('BARRIER CONTACT');beep(80,.07);c.hit=now;}}}
 let ds=near.s-c.s;if(ds< -track.length/2)ds+=track.length;if(ds>track.length/2)ds-=track.length;c.total+=ds;c.s=near.s;
 if(i===0){let result=race.advance(c.s);if(result==='lap'){if(!assisted){bestLap=Math.min(bestLap,race.lapTimes.at(-1));storeBest();}notify(`LAP ${race.lap} / ${formatTime(race.lapTimes.at(-1))}`);beep(750,.16);}else if(result==='checkpoint')notify(`CHECKPOINT ${race.nextCheckpoint-1} / 7`);else if(result==='finish')finish();if(input.drift&&Math.abs(c.speed)>12){skidClock+=dt;if(skidClock>.045){tireMarks();skidClock=0;}}}
 updateCar(c,dt);
 }
 for(let i=0;i<cars.length;i++)for(let j=i+1;j<cars.length;j++){const a=cars[i],b=cars[j],dx=a.x-b.x,dz=a.z-b.z,d=Math.hypot(dx,dz);if(d<2.65&&d>.001){const nx=dx/d,nz=dz/d,push=(2.65-d)*.5;a.x+=nx*push;a.z+=nz*push;b.x-=nx*push;b.z-=nz*push;const closing=(a.vx-b.vx)*nx+(a.vz-b.vz)*nz;if(closing<0){a.vx-=closing*nx*.6;a.vz-=closing*nz*.6;b.vx+=closing*nx*.6;b.vz+=closing*nz*.6;a.speed*=.98;b.speed*=.98;}}}
}
const map=$('map').getContext('2d');function drawMap(){map.clearRect(0,0,220,170);const xy=p=>[(p.x+185)*.39+10,(p.z+230)*.33+8];map.beginPath();track.samples.forEach((p,i)=>{const [x,y]=xy(p);i?map.lineTo(x,y):map.moveTo(x,y);});map.closePath();map.strokeStyle='#111e2877';map.lineWidth=9;map.stroke();map.strokeStyle='#d0c6a680';map.lineWidth=2;map.stroke();for(let i=3;i>=0;i--){const [x,y]=xy(cars[i]);map.beginPath();map.arc(x,y,i?2.7:4,0,Math.PI*2);map.fillStyle=colors[i];map.fill();if(i===0){map.strokeStyle='#fff';map.lineWidth=1.2;map.stroke();}}}
let hudClock=0;function hud(dt){hudClock+=dt;if(hudClock<.07)return;hudClock=0;$('position').textContent=getPosition();$('lap').innerHTML=`0${race.lap} <small>/ 03</small>`;$('raceTime').textContent=formatTime(race.elapsed);$('lapTime').textContent=formatTime(race.elapsed-race.lapStart);$('bestTime').textContent=formatTime(bestLap);$('speed').textContent=String(Math.round(Math.abs(player.speed)*3.6)).padStart(3,'0');$('rpm').style.width=`${Math.abs(player.speed)/64*100}%`;$('gear').textContent=player.speed<-.2?'R':player.speed<.5?'N':Math.min(6,1+Math.floor(player.speed/12));$('cpbar').style.width=`${((race.lap-1)+player.s/track.length)/3*100}%`;$('drivemode').textContent=keys.Space&&player.speed>12?'DRIFT / HOLD YOUR LINE':'ÉCLAT / V12';$('count').innerHTML=race.state==='countdown'?`${Math.max(1,Math.ceil(race.countdown))}<small>THE CROWN IS CALLING</small>`:'';if(now>toastEnd)$('toast').textContent=Math.abs(angle(player.heading-track.at(player.s).heading))>2&&player.speed>4?'WRONG WAY / TURN AROUND':'';drawMap();}
function frame(time){requestAnimationFrame(frame);const dt=Math.min((time-last)/1000,.1);last=time;now+=dt;accumulator+=dt;while(accumulator>=1/120){physics(1/120);accumulator-=1/120;}
 if(race.state==='grid'){
 const p=track.at(2);const a=p.heading+.92+Math.sin(now*.12)*.07;camera.position.set(player.x+Math.sin(a)*9,4.0,player.z+Math.cos(a)*9);const target=new T.Vector3(player.x,1,player.z);camera.lookAt(target);camera.setViewOffset(innerWidth,innerHeight,-innerWidth*.21,0,innerWidth,innerHeight);camera.fov=43;camera.updateProjectionMatrix();cars.slice(1).forEach(c=>c.model.visible=false);
 }else{cars.forEach(c=>c.model.visible=true);camera.clearViewOffset();const h=player.heading;const desired=new T.Vector3(player.x-Math.sin(h)*(10.5+Math.abs(player.speed)*.035),5.5+Math.abs(player.speed)*.015,player.z-Math.cos(h)*(10.5+Math.abs(player.speed)*.035));if(!camReady){camera.position.copy(desired);camReady=true;}else camera.position.lerp(desired,1-Math.exp(-dt*5.5));const target=new T.Vector3(player.x+Math.sin(h)*5,1.5,player.z+Math.cos(h)*5);camera.lookAt(target);camera.fov=T.MathUtils.lerp(camera.fov,54+Math.abs(player.speed)*.16,1-Math.exp(-dt*3));camera.updateProjectionMatrix();hud(dt);}
 sun.position.set(player.x-100,160,player.z+80);sun.target.position.set(player.x,0,player.z);sun.target.updateMatrixWorld();sky.position.copy(camera.position);
 if(audio){const active=sound&&!paused&&race.state==='racing';audio.gain.gain.setTargetAtTime(active?.035:0,audio.ctx.currentTime,.1);const rpm=60+(Math.abs(player.speed)%12)*8+Math.abs(player.speed)*.6;audio.osc.frequency.setTargetAtTime(rpm,audio.ctx.currentTime,.1);audio.sub.frequency.setTargetAtTime(rpm*.5,audio.ctx.currentTime,.1);audio.filter.frequency.setTargetAtTime(350+Math.abs(player.speed)*10,audio.ctx.currentTime,.1);}
 renderer.render(scene,camera);
 // Read-only diagnostics support verification without adding gameplay shortcuts.
 $('game').dataset.state=JSON.stringify({state:race.state,paused,demo,lap:race.lap,checkpoints:race.nextCheckpoint-1,elapsed:+race.elapsed.toFixed(2),speed:+player.speed.toFixed(2),x:+player.x.toFixed(2),z:+player.z.toFixed(2),heading:+player.heading.toFixed(3),distance:+player.s.toFixed(1),trackLength:+track.length.toFixed(1),position:getPosition(),collisions:collisionCount,lapTimes:race.lapTimes,drawCalls:renderer.info.render.calls,triangles:renderer.info.render.triangles});
}
addEventListener('resize',()=>{renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();});canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();if(!paused)togglePause();$('load').hidden=false;$('load').textContent='Graphics paused. Reload to restore the game.';});
